/* let HAS let BEEN let BEFORE. (Sarcasm) every user needs there own one to show off though. */

let bubbles = new ArrayList();
let lines = false;
let clickOnce;

function setup() {
  createCanvas(1200, 640);
  frameRate(60);
  noStroke();

  for (i = 0; i <= 150; i++) {
    bubbles.add(new Bubble(new PVector(random(width), random(height)), random(5, 10)));
  }
}

function draw() {
  background(255);

  for (i = 0; i < bubbles.size(); i++) {
    let b = (Bubble) bubbles.get(i);
    if (lines) {
      for (q = 0; q < bubbles.size(); q++) {
        let b2 = (Bubble) bubbles.get(q);
        let d = PVector.dist(b.loc, b2.loc);
        if (d < 100) {
          stroke(100, 25, 235, 80);
          line(b.loc.x, b.loc.y, b2.loc.x, b2.loc.y);
        }
      }
    }
    b.draw();
    b.moveBubble();
    //b.applyForce(gravity);
    b.boundaries();
  }
  fill(0);
  text(int(frameRate), 5, 10);
}

function mousePressed() {
  if (lines && clickOnce == false) {
    lines = false;
    clickOnce = true;
  }
  else if (!lines && clickOnce == false) {
    lines = true;
    clickOnce = true;
  }
}

function mouseReleased() {
  clickOnce = false;
}

class Bubble {
  loc;
  acc;
  vel;

  mass = 1;
  size;

  constructor(loc_, size_) {
    loc = loc_;
    vel = new PVector(random(-3, 3), random(-3, 3));

    size = size_;
  }

  function draw() {
    noStroke();
    fill(255, 255);
    ellipse(loc.x, loc.y, size+1, size+1);
    fill(255);
    ellipse(loc.x, loc.y, size, size);
  }

  function moveBubble() {
    loc.add(vel);
  }
  function boundaries() {
    if (loc.y < 0)
      vel.y *= -1;
    if (loc.y > height)
      vel.y *= -1;
    if (loc.x > width)
      vel.x *= -1;
    if (loc.x < 0)
      vel.x *= -1;
  }
}

